// «Разобрать апдейт»: turns a Telegram update into one action for the bot.
// Only private chats are answered; anything else produces no items and the run stops.

const MENU_CALC = '🧮 Калькулятор';
const MENU_ASK = '💬 Задать вопрос';

const update = $input.first().json;
let chatId = null;
let chatType = 'private';
let firstName = '';
let callbackId = null;
let action = 'unknown';
let from = null;

if (update.callback_query) {
  const cq = update.callback_query;
  chatId = cq.message?.chat?.id ?? cq.from?.id ?? null;
  chatType = cq.message?.chat?.type ?? 'private';
  firstName = cq.from?.first_name ?? '';
  from = cq.from ?? null;
  callbackId = cq.id;
  action = cq.data === 'retry_calc' ? 'retry' : 'unknown';
} else if (update.message) {
  const m = update.message;
  chatId = m.chat?.id ?? null;
  chatType = m.chat?.type ?? 'private';
  firstName = m.from?.first_name ?? '';
  from = m.from ?? null;
  const text = (m.text ?? '').trim();
  if (/^\/start(\s|@|$)/.test(text)) action = 'start';
  else if (text === MENU_CALC || /^\/calc(\s|@|$)/.test(text)) action = 'calculator';
  else if (text === MENU_ASK || /^\/(ask|help)(\s|@|$)/.test(text)) action = 'question';
}

if (!chatId || chatType !== 'private') return [];

return [
  {
    json: {
      chatId,
      firstName,
      callbackId,
      action,
      // Only these actions show the calculator button, so only they need the availability check.
      needsCheck: ['start', 'calculator', 'retry'].includes(action),
      // Name and username for the bot_users table (language and Premium are not kept).
      user: from
        ? {
            id: from.id,
            username: from.username ?? '',
            first_name: from.first_name ?? '',
            last_name: from.last_name ?? '',
          }
        : null,
    },
  },
];

// «Собрать ответ»: decides what the bot sends. Each output item is one Bot API call
// ({ method, payload }); the next node sends them in order.
// Links and texts come from environment variables set in docker-compose (.env).

const MENU_CALC = '🧮 Калькулятор';
const MENU_ASK = '💬 Задать вопрос';

const p = $('Разобрать апдейт').first().json;
const calcUrl = $env.CALCULATOR_URL;
const policyUrl = $env.PD_POLICY_URL;
const consentUrl = $env.PD_CONSENT_URL;
const specialistUrl = $env.SPECIALIST_URL;

const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// The calculator counts as available only if its page answered 2xx and is really our app.
let available = false;
if (p.needsCheck) {
  const r = $input.first().json;
  const body = typeof r.body === 'string' ? r.body : typeof r.data === 'string' ? r.data : '';
  available = !r.error && r.statusCode >= 200 && r.statusCode < 300 && body.includes('sovest-mortgage-calculator');
}

const menuKeyboard = {
  keyboard: [[{ text: MENU_CALC }, { text: MENU_ASK }]],
  resize_keyboard: true,
  is_persistent: true,
};
const calcButton = { inline_keyboard: [[{ text: '🧮 Открыть калькулятор', web_app: { url: calcUrl } }]] };
const retryButton = { inline_keyboard: [[{ text: '🔄 Повторить', callback_data: 'retry_calc' }]] };

const send = (text, reply_markup) => ({
  json: {
    method: 'sendMessage',
    payload: { chat_id: p.chatId, text, parse_mode: 'HTML', link_preview_options: { is_disabled: true }, reply_markup },
  },
});

const unavailable = () =>
  send(
    'Калькулятор сейчас не открывается — похоже, на сервере неполадки.\n\n' +
      'Попробуйте ещё раз через пару минут: нажмите «Повторить».',
    retryButton,
  );

const welcomeText =
  `Здравствуйте${p.firstName ? `, ${esc(p.firstName)}` : ''}! 👋\n\n` +
  'Это ипотечный калькулятор центра недвижимости «Совесть». ' +
  'Он покажет ежемесячный платёж, переплату и то, как досрочные погашения сокращают срок и проценты.\n\n' +
  '⚠️ <b>Калькулятор носит ознакомительный характер.</b> Расчёт не является публичной офертой; ' +
  'точные условия кредита определяет банк.\n\n' +
  'Пользуясь ботом, вы соглашаетесь с ' +
  `<a href="${esc(policyUrl)}">политикой обработки персональных данных</a> и даёте ` +
  `<a href="${esc(consentUrl)}">согласие на обработку персональных данных</a>.`;

const out = [];

if (p.callbackId) {
  // Stops the loading spinner on the pressed inline button.
  out.push({ json: { method: 'answerCallbackQuery', payload: { callback_query_id: p.callbackId } } });
}

switch (p.action) {
  case 'start':
    if (available) {
      out.push(send(welcomeText, calcButton));
      // A message carries either buttons under it or the bottom menu, so the menu comes in a short second message.
      out.push(send('Меню 👇', menuKeyboard));
    } else {
      out.push(send(welcomeText, menuKeyboard));
      out.push(unavailable());
    }
    break;
  case 'calculator':
  case 'retry':
    out.push(available ? send('Откройте калькулятор по кнопке ниже:', calcButton) : unavailable());
    break;
  case 'question':
    out.push(
      send(
        'Ответим на вопросы об ипотеке, объектах и сделке. Напишите нашему специалисту — он ответит в личных сообщениях.',
        { inline_keyboard: [[{ text: '✉️ Написать специалисту', url: specialistUrl }]] },
      ),
    );
    break;
  default:
    out.push(send('Выберите действие в меню ниже 👇', menuKeyboard));
}

return out;

// «Карточка пользователя»: one bot_users row per Telegram user, refreshed on every message.
// Only what Telegram itself sends with an update; phone numbers are not requested.
// The table's own createdAt column = first visit, updatedAt = last activity.

const p = $('Разобрать апдейт').first().json;
const u = p.user;
if (!u || !u.id) return [];

const clip = (s, n) => String(s ?? '').slice(0, n);

return [
  {
    json: {
      telegram_id: String(u.id),
      username: clip(u.username, 64),
      profile_link: u.username ? `https://t.me/${clip(u.username, 64)}` : '',
      first_name: clip(u.first_name, 128),
      last_name: clip(u.last_name, 128),
      last_action: p.action,
      last_seen_at: new Date().toISOString(),
    },
  },
];

// «Проверить подпись Telegram»: validates Mini App initData (HMAC-SHA256 with the bot token,
// https://core.telegram.org/bots/webapps#validating-data-received-via-the-mini-app)
// and turns the calculation into one Data Table row keyed by the Telegram user ID.
// The user ID is taken only from the signed initData, never from the request body.

const crypto = require('crypto');

const MAX_AGE_SECONDS = 24 * 60 * 60;
const NUMBER_FIELDS = [
  'price',
  'down_payment',
  'loan_amount',
  'term_months',
  'rate',
  'monthly_payment',
  'total_interest',
  'overpayment_pct',
  'total_paid',
  'actual_term_months',
  'prepaid_total',
  'saved_interest',
];
const STRING_FIELDS = ['start_month', 'prepayments', 'last_payment_month'];

const fail = (status, error) => [{ json: { valid: false, status, error } }];

const body = $input.first().json.body ?? {};
const token = $env.TELEGRAM_BOT_TOKEN;
if (!token) return fail(500, 'bot_token_not_configured');
if (typeof body.initData !== 'string' || !body.calculation || typeof body.calculation !== 'object') {
  return fail(400, 'bad_request');
}

// 1. Signature. (URLSearchParams is not available in the Code-node sandbox, so parse by hand.)
const decode = (s) => {
  try {
    return decodeURIComponent(s.replace(/\+/g, ' '));
  } catch {
    return null;
  }
};
const params = new Map();
for (const part of body.initData.split('&')) {
  if (!part) continue;
  const eq = part.indexOf('=');
  const key = decode(eq < 0 ? part : part.slice(0, eq));
  const value = decode(eq < 0 ? '' : part.slice(eq + 1));
  if (key === null || value === null) return fail(401, 'bad_init_data');
  params.set(key, value);
}
const hash = params.get('hash');
if (!hash) return fail(401, 'no_signature');
params.delete('hash');
const dataCheckString = [...params.entries()]
  .sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0))
  .map(([k, v]) => `${k}=${v}`)
  .join('\n');
const secret = crypto.createHmac('sha256', 'WebAppData').update(token).digest();
const expected = crypto.createHmac('sha256', secret).update(dataCheckString).digest('hex');
if (expected.length !== hash.length || !crypto.timingSafeEqual(Buffer.from(expected), Buffer.from(hash))) {
  return fail(401, 'bad_signature');
}

// 2. Freshness: initData older than a day is refused.
const authDate = Number(params.get('auth_date'));
if (!Number.isFinite(authDate) || Date.now() / 1000 - authDate > MAX_AGE_SECONDS) return fail(401, 'expired');

// 3. User.
let user;
try {
  user = JSON.parse(params.get('user') ?? '');
} catch {
  return fail(401, 'no_user');
}
if (!user || !user.id) return fail(401, 'no_user');

// 4. Calculation.
const c = body.calculation;
const row = {
  telegram_id: String(user.id),
  username: String(user.username ?? '').slice(0, 64),
  first_name: String(user.first_name ?? '').slice(0, 128),
  last_name: String(user.last_name ?? '').slice(0, 128),
};
for (const k of NUMBER_FIELDS) {
  const v = Number(c[k]);
  if (!Number.isFinite(v) || v < 0 || v > 1e12) return fail(400, `bad_field_${k}`);
  row[k] = v;
}
for (const k of STRING_FIELDS) {
  if (typeof c[k] !== 'string') return fail(400, `bad_field_${k}`);
  row[k] = c[k].slice(0, 2000);
}
row.saved_at = new Date().toISOString();

return [{ json: { valid: true, row } }];
